//! The root types of the app's schema: `Query`, `Mutation` and
//! `Subscription`, merged at boot from every registered resolver.
//!
//! async-graphql builds a schema from root types known at compile time;
//! Navree's resolvers are registered by modules at run time. Each resolver
//! contributes objects (one per kind, generated by `#[resolver]`), held here
//! as [`ErasedObject`] / [`ErasedSubscription`]. The roots copy the fields
//! of every part into one object type when the schema is built (the parts
//! are handed over through a thread-local for the duration of
//! `Schema::build`, since async-graphql asks root types for their type
//! information through static functions), and dispatch each root field to
//! the part that defines it.

use std::borrow::Cow;
use std::cell::RefCell;
use std::collections::HashMap;
use std::pin::Pin;
use std::sync::Arc;

use async_graphql::futures_util::stream::Stream;
use async_graphql::indexmap::IndexMap;
use async_graphql::parser::types::Field;
use async_graphql::registry::{MetaType, MetaTypeId, Registry};
use async_graphql::{
    CacheControl, ContainerType, Context, ContextSelectionSet, ObjectType, OutputType, Positioned,
    Response, ServerResult, SubscriptionType, Value,
};
use navree_kernel::BoxFuture;

/// A query or mutation object of one resolver, as the roots hold it.
pub trait ErasedObject: Send + Sync + 'static {
    /// The object's type information (registers the types it uses).
    fn meta(&self, registry: &mut Registry) -> MetaType;

    /// Resolves the field `ctx` selects; `None` when it is not this
    /// object's.
    fn resolve_field<'a>(
        &'a self,
        ctx: &'a Context<'_>,
    ) -> BoxFuture<'a, ServerResult<Option<Value>>>;
}

impl<T: ObjectType + 'static> ErasedObject for T {
    fn meta(&self, registry: &mut Registry) -> MetaType {
        registry.create_fake_output_type::<T>()
    }

    fn resolve_field<'a>(
        &'a self,
        ctx: &'a Context<'_>,
    ) -> BoxFuture<'a, ServerResult<Option<Value>>> {
        Box::pin(ContainerType::resolve_field(self, ctx))
    }
}

/// The subscription object of one resolver, as the root holds it.
pub trait ErasedSubscription: Send + Sync + 'static {
    /// The object's type information (registers the types it uses).
    fn meta(&self, registry: &mut Registry) -> MetaType;

    /// The stream of the field `ctx` selects; `None` when it is not this
    /// object's.
    fn create_field_stream<'a>(
        &'a self,
        ctx: &'a Context<'_>,
    ) -> Option<Pin<Box<dyn Stream<Item = Response> + Send + 'a>>>;
}

impl<T: SubscriptionType + 'static> ErasedSubscription for T {
    fn meta(&self, registry: &mut Registry) -> MetaType {
        registry.create_fake_subscription_type::<T>()
    }

    fn create_field_stream<'a>(
        &'a self,
        ctx: &'a Context<'_>,
    ) -> Option<Pin<Box<dyn Stream<Item = Response> + Send + 'a>>> {
        SubscriptionType::create_field_stream(self, ctx)
    }
}

/// The parts of one root and which part defines each field.
pub(crate) struct Parts<P: ?Sized> {
    pub(crate) parts: Vec<Arc<P>>,
    pub(crate) index: HashMap<String, usize>,
}

impl<P: ?Sized> Parts<P> {
    pub(crate) fn new(parts: Vec<Arc<P>>, index: HashMap<String, usize>) -> Self {
        Self { parts, index }
    }

    fn part(&self, ctx: &Context<'_>) -> Option<&Arc<P>> {
        let name = ctx.item.node.name.node.as_str();
        self.index.get(name).map(|&i| &self.parts[i])
    }
}

/// The parts being built into a schema (see the module docs).
#[derive(Clone, Default)]
pub(crate) struct Building {
    pub(crate) query: Vec<Arc<dyn ErasedObject>>,
    pub(crate) mutation: Vec<Arc<dyn ErasedObject>>,
    pub(crate) subscription: Vec<Arc<dyn ErasedSubscription>>,
}

thread_local! {
    static BUILDING: RefCell<Option<Building>> = const { RefCell::new(None) };
}

/// Runs `f` (which builds the schema) with `building` handed to the root
/// types.
pub(crate) fn with_building<R>(building: Building, f: impl FnOnce() -> R) -> R {
    struct Reset;
    impl Drop for Reset {
        fn drop(&mut self) {
            BUILDING.with(|cell| cell.borrow_mut().take());
        }
    }
    BUILDING.with(|cell| *cell.borrow_mut() = Some(building));
    let _reset = Reset;
    f()
}

fn building() -> Building {
    BUILDING.with(|cell| cell.borrow().clone().unwrap_or_default())
}

/// An object type named `name` with every field of `metas`.
fn object(
    name: &str,
    metas: Vec<MetaType>,
    rust_typename: &'static str,
    subscription: bool,
) -> MetaType {
    let mut fields = IndexMap::new();
    for meta in metas {
        if let MetaType::Object {
            fields: part_fields,
            ..
        } = meta
        {
            fields.extend(part_fields);
        }
    }
    MetaType::Object {
        name: name.to_owned(),
        description: None,
        fields,
        cache_control: CacheControl::default(),
        extends: false,
        shareable: false,
        resolvable: true,
        keys: None,
        visible: None,
        inaccessible: false,
        interface_object: false,
        tags: Vec::new(),
        is_subscription: subscription,
        rust_typename: Some(rust_typename),
        directive_invocations: Vec::new(),
        requires_scopes: Vec::new(),
    }
}

/// The `Query` root.
pub(crate) struct RootQuery(pub(crate) Arc<Parts<dyn ErasedObject>>);

/// The `Mutation` root (absent from the schema when no resolver has a
/// mutation).
pub(crate) struct RootMutation(pub(crate) Arc<Parts<dyn ErasedObject>>);

/// The `Subscription` root (absent when no resolver has a subscription).
pub(crate) struct RootSubscription(pub(crate) Arc<Parts<dyn ErasedSubscription>>);

macro_rules! object_root {
    ($root:ident, $name:literal, $slot:ident) => {
        impl OutputType for $root {
            fn type_name() -> Cow<'static, str> {
                Cow::Borrowed($name)
            }

            fn create_type_info(registry: &mut Registry) -> String {
                registry.create_output_type::<Self, _>(MetaTypeId::Object, |registry| {
                    let metas = building()
                        .$slot
                        .iter()
                        .map(|part| part.meta(registry))
                        .collect();
                    object($name, metas, std::any::type_name::<Self>(), false)
                })
            }

            async fn resolve(
                &self,
                ctx: &ContextSelectionSet<'_>,
                _field: &Positioned<Field>,
            ) -> ServerResult<Value> {
                async_graphql::resolver_utils::resolve_container(ctx, self).await
            }
        }

        impl ContainerType for $root {
            fn is_empty() -> bool {
                building().$slot.is_empty()
            }

            async fn resolve_field(&self, ctx: &Context<'_>) -> ServerResult<Option<Value>> {
                match self.0.part(ctx) {
                    Some(part) => part.resolve_field(ctx).await,
                    None => Ok(None),
                }
            }
        }

        impl ObjectType for $root {}
    };
}

object_root!(RootQuery, "Query", query);
object_root!(RootMutation, "Mutation", mutation);

impl SubscriptionType for RootSubscription {
    fn type_name() -> Cow<'static, str> {
        Cow::Borrowed("Subscription")
    }

    fn create_type_info(registry: &mut Registry) -> String {
        registry.create_subscription_type::<Self, _>(|registry| {
            let metas = building()
                .subscription
                .iter()
                .map(|part| part.meta(registry))
                .collect();
            object("Subscription", metas, std::any::type_name::<Self>(), true)
        })
    }

    fn is_empty() -> bool {
        building().subscription.is_empty()
    }

    fn create_field_stream<'a>(
        &'a self,
        ctx: &'a Context<'_>,
    ) -> Option<Pin<Box<dyn Stream<Item = Response> + Send + 'a>>> {
        self.0.part(ctx)?.create_field_stream(ctx)
    }
}

/// The field names of a part's object type.
pub(crate) fn field_names(meta: &MetaType) -> Vec<String> {
    match meta {
        MetaType::Object { fields, .. } => fields.keys().cloned().collect(),
        _ => Vec::new(),
    }
}
